// Method: Node::replace_by
static JSValue js_Node_replace_by(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Node.replace_by: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Node.replace_by: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Node.replace_by: invalid or freed object");
    }

    Node* typed_obj = Object::cast_to<Node>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Node.replace_by: object is not a Node");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Node.replace_by: expected at least 1 arguments, got %d", argc - 1);
    }

    // Convert arguments
    Node* arg_node = nullptr;
    if (JS_IsNumber(argv[1])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_node; JS_ToInt64(ctx, &h_node, argv[1]);
        Object* obj_node = qjs_ctx->get_object_registry()->get_object(h_node);
        arg_node = reinterpret_cast<Node*>(obj_node);
    } else {
        // Object with __handle property
        JSValue jh_node = JS_GetPropertyStr(ctx, argv[1], "__handle");
        if (!JS_IsUndefined(jh_node)) {
            int64_t h_node; JS_ToInt64(ctx, &h_node, jh_node);
            Object* obj_node = qjs_ctx->get_object_registry()->get_object(h_node);
            arg_node = reinterpret_cast<Node*>(obj_node);
        }
        JS_FreeValue(ctx, jh_node);
    }
    // Optional argument: keep_groups (default: false)
    bool arg_keep_groups = false;
    if (argc > 2) {
        // Override default with provided value
        arg_keep_groups = JS_ToBool(ctx, argv[2]);
    }

    typed_obj->replace_by(arg_node, arg_keep_groups);
    return JS_UNDEFINED;
}

