    if (!obj) {
        return JS_ThrowTypeError(ctx, "Node.get_viewport: invalid or freed object");
    }

    Node* typed_obj = Object::cast_to<Node>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Node.get_viewport: object is not a Node");
    }

    Viewport* result = typed_obj->get_viewport();
    if (!result) return JS_NULL;
