// Property getter: Node::owner
static JSValue js_Node_get_owner(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Node.owner getter: missing handle");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Node.owner getter: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Node.owner getter: invalid object");
    }

    Node* typed_obj = Object::cast_to<Node>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Node.owner getter: wrong type");
    }

    Node* value = typed_obj->get_owner();
    if (!value) return JS_NULL;
    Object* ret_obj_ptr = reinterpret_cast<Object*>(value);
    int64_t ret_handle = qjs_ctx->get_object_registry()->get_or_create_handle(ret_obj_ptr);
    JSValue ret_obj = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, ret_obj, "__handle", JS_NewInt64(ctx, ret_handle));
    JS_SetPropertyStr(ctx, ret_obj, "__class", JS_NewString(ctx, ret_obj_ptr->get_class().utf8().get_data()));
    return ret_obj;
}

// Property setter: Node::owner
static JSValue js_Node_set_owner(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Node.owner setter: missing arguments");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Node.owner setter: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Node.owner setter: invalid object");
    }

    Node* typed_obj = Object::cast_to<Node>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Node.owner setter: wrong type");
    }

    Node* value = nullptr;
    if (JS_IsNumber(argv[1])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_value; JS_ToInt64(ctx, &h_value, argv[1]);
        Object* obj_value = qjs_ctx->get_object_registry()->get_object(h_value);
        value = reinterpret_cast<Node*>(obj_value);
    } else {
        // Object with __handle property
        JSValue jh_value = JS_GetPropertyStr(ctx, argv[1], "__handle");
        if (!JS_IsUndefined(jh_value)) {
            int64_t h_value; JS_ToInt64(ctx, &h_value, jh_value);
            Object* obj_value = qjs_ctx->get_object_registry()->get_object(h_value);
            value = reinterpret_cast<Node*>(obj_value);
        }
        JS_FreeValue(ctx, jh_value);
    }
    typed_obj->set_owner(value);
    return JS_UNDEFINED;
}

